package com.bank.routing;

import java.util.List;
import java.util.logging.*;

public class TopicStrategyDemo {

    private static final Logger log = Logger.getLogger(TopicStrategyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<String> types     = List.of("credit", "debit", "transfer");
        List<String> countries = List.of("IN", "BR", "US", "UK");
        List<String> bands      = List.of("small", "medium", "large");

        // ---------- KAFKA: topics multiply with dimensions ----------
        log.info("=== KAFKA per-combination topics ===");
        KafkaTopicPlanner planner = new KafkaTopicPlanner(6, 3); // 6 partitions, RF 3
        int count = planner.planTopics(types, countries, bands);
        log.info(() -> "Kafka topics required = " + count
                + ", partitions provisioned = " + (count * 6));

        // Compliance adds a 4th band mid-quarter.
        List<String> bandsV2 = List.of("small", "medium", "large", "veryLarge");
        int count2 = planner.planTopics(types, countries, bandsV2);
        log.warning(() -> "After adding one band: topics jump from "
                + count + " to " + count2 + " (rewire producers + ACLs + dashboards)");

        // ---------- SOLACE: one namespace, patterns only ----------
        log.info("=== SOLACE single hierarchical namespace ===");
        SolaceNamespace ns = new SolaceNamespace();
        ns.subscribe("brazil-large-desk", "txn/BR/*/large");       // Brazil, any type, large
        ns.subscribe("mumbai-ops-desk",   "txn/IN/>");             // everything India
        // New compliance rule = ONE new subscription, ZERO new topics.
        ns.subscribe("verylarge-monitor", "txn/*/*/veryLarge");
        log.info(() -> "Solace topics created = " + ns.createdTopicCount()
                + " (always zero), subscriptions = " + ns.subscriptionCount());
        // A sample publish just works, no pre-provisioning.
        ns.publish("txn/BR/transfer/large", "Priya CUR3001 large transfer");
        ns.publish("txn/IN/credit/veryLarge", "Rajesh SAV2001 very large credit");
    }
}

// ─── Would be in kafka/KafkaTopicPlanner.java ───
class KafkaTopicPlanner {
    private static final Logger log = Logger.getLogger(KafkaTopicPlanner.class.getName());
    private final int partitions;
    private final int replication;
    KafkaTopicPlanner(int partitions, int replication) {
        this.partitions = partitions; this.replication = replication;
    }

    // Cartesian product => multiplicative topic count.
    int planTopics(List<String> types, List<String> countries, List<String> bands) {
        int created = 0;
        for (String t : types)
            for (String c : countries)
                for (String b : bands) {
                    String topic = "txn." + t + "." + c + "." + b;
                    created++;
                    log.fine(() -> "CREATE topic " + topic
                            + " partitions=" + partitions + " rf=" + replication);
                }
        return created;
    }
}

