class SolaceNamespace {
    private static final Logger log = Logger.getLogger(SolaceNamespace.class.getName());
    private final java.util.Map<String, String> subs = new java.util.LinkedHashMap<>();

    int createdTopicCount() { return 0; }            // topics are never pre-created
    int subscriptionCount() { return subs.size(); }

    void subscribe(String name, String pattern) {
        subs.put(name, pattern);
        log.info(() -> "subscribe " + name + " -> " + pattern + " (no topic created)");
    }

    void publish(String topic, String payload) {
        for (var e : subs.entrySet())
            if (matches(e.getValue(), topic))
                log.info(() -> "DELIVER to " + e.getKey() + " : " + topic + " [" + payload + "]");
    }

    boolean matches(String pattern, String topic) {
        String[] p = pattern.split("/"), t = topic.split("/");
        int i = 0;
        for (; i < p.length; i++) {
            if (p[i].equals(">")) return true;
            if (i >= t.length) return false;
            if (p[i].equals("*")) continue;
            if (!p[i].equals(t[i])) return false;
        }
        return i == t.length;
    }
}

